// French/Spanish/Italian contain a few deliberately concise fallbacks above;
// these two full catalogs complete the supported set while retaining the same
// stable keys as English.
export const DEMO_CATALOGS = Object.freeze(CATALOGS);

export function demoTranslate(locale, key, vars) {
  const code = normalizeDemoLocale(locale) || 'en';
  const value = DEMO_CATALOGS[code]?.[key] ?? EN[key] ?? key;
  if (!vars) return value;
  return value.replace(/\{\{(\w+)\}\}/g, (match, name) => name in vars ? String(vars[name]) : match);
}

export function demoCatalog(locale) {
  const code = normalizeDemoLocale(locale) || 'en';
  return DEMO_CATALOGS[code] || EN;
}

export const DEMO_CATALOG_KEYS = Object.freeze(Object.keys(EN));
